// src/data/pages.rs
//
// What the game draws from Wikipedia and Wikidata: `assets/data/pages.ron`, generated by
// tools/data/gen_pages.py. For each substance with an article it can confirm, the article's
// lead and a few of its sections (history, how it is made, where it is found, uses,
// safety); the measured values the game shows (melting and boiling points, density) as
// checked against the article and Wikidata; the curriculum: the ideas behind the reactions,
// each a Wikipedia article, grouped into units, with which of them explain each reaction,
// vessel and era; and the glossary (tools/data/glossary.py): the chemistry words the pages
// use, each defined, with which of them each substance's page and each lesson uses.
use super::common::ProcessType;
use super::substances::Substances;
use bevy::{asset::Asset, reflect::TypePath};
use serde::Deserialize;
use std::collections::HashMap;

#[derive(Debug, Deserialize, Asset, TypePath, Clone, Default)]
#[serde(default)]
pub struct Pages {
    /// the curriculum's units in teaching order: (key, title)
    pub units: Vec<(String, String)>,
    /// every curriculum topic, by key
    pub topics: HashMap<String, Topic>,
    /// reaction id -> the topics that explain it, most telling first
    pub reactions: HashMap<u32, Vec<String>>,
    /// the topics behind each vessel: what it is, then what it does
    pub vessels: HashMap<ProcessType, Vec<String>>,
    /// the events of each era, by the era's name
    pub eras: HashMap<String, Vec<String>>,
    /// substance id -> its page
    pub substances: HashMap<u32, SubstancePage>,
    /// substance id -> its measured values, checked (None: not known, or the sources disagree)
    pub values: HashMap<u32, Measured>,
    /// every glossary term, by key
    pub glossary: HashMap<String, Term>,
    /// substance id -> the terms its page uses, in order of first use
    pub substance_terms: HashMap<u32, Vec<String>>,
    /// topic key -> the terms its lesson uses
    pub topic_terms: HashMap<String, Vec<String>>,
}

/// A chemistry word, defined.
#[derive(Debug, Deserialize, Clone, Default)]
#[serde(default)]
pub struct Term {
    /// the word as a heading ("Nitrite", "-ate and -ite")
    pub term: String,
    /// the definition, a sentence or two
    pub text: String,
    /// the Wikipedia article that explains it
    pub url: String,
    /// the curriculum topic that teaches it
    pub lesson: Option<String>,
    /// the words in running text that mean it, longest first; lowercase ones match any case,
    /// one with a capital ("pH") only as written
    pub forms: Vec<String>,
}

#[derive(Debug, Deserialize, Clone, Copy, PartialEq, Eq, Hash)]
pub enum TopicKind {
    Law,
    Concept,
    Technique,
    Process,
    Apparatus,
    Event,
}

impl TopicKind {
    pub fn label(self) -> &'static str {
        match self {
            TopicKind::Law => "Law or rule",
            TopicKind::Concept => "Idea",
            TopicKind::Technique => "Technique",
            TopicKind::Process => "Process",
            TopicKind::Apparatus => "Apparatus",
            TopicKind::Event => "History",
        }
    }
}

#[derive(Debug, Deserialize, Clone)]
pub struct Topic {
    pub unit: String,
    pub kind: TopicKind,
    /// the Wikipedia article's title
    pub title: String,
    pub url: String,
    /// the article's lead (empty until the articles are fetched)
    #[serde(default)]
    pub lead: String,
}

#[derive(Debug, Deserialize, Clone, Default)]
#[serde(default)]
pub struct SubstancePage {
    /// the article's title, its link and the date of the revision the text is from
    pub title: String,
    pub url: String,
    pub revised: String,
    /// Set when the article is about a related subject the content links on purpose (an
    /// oxide's element, the drug an intermediate makes, a crop's plant): its title. The text
    /// is shown under it, and the article's measured values aren't the substance's.
    pub about: Option<String>,
    /// Wikipedia's one-line description ("Chemical compound")
    pub summary: Option<String>,
    pub lead: String,
    /// (heading, text): up to four of the article's sections
    pub sections: Vec<(String, String)>,
    pub appearance: Option<String>,
    pub odor: Option<String>,
    /// in water, as the article gives it ("36 g/100 mL (20 °C)")
    pub solubility: Option<String>,
}

#[derive(Debug, Deserialize, Clone, Default, PartialEq)]
#[serde(default)]
pub struct Measured {
    pub melting_c: Option<f32>,
    pub boiling_c: Option<f32>,
    pub density: Option<f32>,
    /// "Decomposes at 132 °C", "Sublimes at −78 °C": said instead of a point that isn't reached
    pub phase_note: Option<String>,
}

impl Pages {
    /// Put the checked values on the substances: each listed substance's melting and boiling
    /// points and density become exactly these (an unknown value clears the library's).
    pub fn apply_values(&self, subs: &mut Substances) -> usize {
        let mut n = 0;
        for (id, m) in &self.values {
            if let Some(s) = subs.0.get_mut(id) {
                s.melting_point_c = m.melting_c;
                s.boiling_point_c = m.boiling_c;
                if m.density.is_some() {
                    s.density_g_cm3 = m.density;
                }
                s.phase_note = m.phase_note.clone();
                n += 1;
            }
        }
        n
    }

    /// The topics that explain a reaction, then the ones behind its vessel, without repeats.
    pub fn reaction_topics(&self, reaction: u32, vessel: &ProcessType) -> Vec<&str> {
        let mut out: Vec<&str> = Vec::new();
        let ours = self.reactions.get(&reaction).into_iter().flatten();
        let vessel = self.vessels.get(vessel).into_iter().flatten();
        for k in ours.chain(vessel) {
            if self.topics.contains_key(k) && !out.contains(&k.as_str()) {
                out.push(k);
            }
        }
        out
    }

    /// The topics of one unit, in the order the curriculum lists them (by title).
    pub fn unit_topics(&self, unit: &str) -> Vec<(&str, &Topic)> {
        let mut v: Vec<(&str, &Topic)> =
            self.topics.iter().filter(|(_, t)| t.unit == unit).map(|(k, t)| (k.as_str(), t)).collect();
        v.sort_by(|a, b| kind_rank(a.1.kind).cmp(&kind_rank(b.1.kind)).then(a.1.title.cmp(&b.1.title)));
        v
    }

    /// Every reaction a topic explains.
    pub fn reactions_of(&self, topic: &str) -> Vec<u32> {
        let mut v: Vec<u32> =
            self.reactions.iter().filter(|(_, ts)| ts.iter().any(|t| t == topic)).map(|(id, _)| *id).collect();
        v.sort_unstable();
        v
    }

    /// Where the given terms are used in `text`: (start, end, term key) byte ranges, in order,
    /// not overlapping, the longest form winning where two start together. A form counts
    /// only as a whole word, and not straight after a hyphen ("non-toxic" isn't "toxic"),
    /// the same rule tools/data/gen_pages.py uses to list a page's terms.
    pub fn term_spans<'a>(&'a self, text: &str, keys: &'a [String]) -> Vec<(usize, usize, &'a str)> {
        let mut forms: Vec<(&str, &str)> = keys
            .iter()
            .filter_map(|k| self.glossary.get(k).map(|t| (k.as_str(), t)))
            .flat_map(|(k, t)| t.forms.iter().map(move |f| (f.as_str(), k)))
            .collect();
        forms.sort_by_key(|(f, _)| std::cmp::Reverse(f.len()));
        // ASCII lowercase keeps every byte where it was, so the offsets hold for `text`
        let lower = text.to_ascii_lowercase();
        let word = |c: char| c.is_alphanumeric() || c == '_';
        let mut out = Vec::new();
        let mut next = 0;
        for (i, c) in text.char_indices() {
            if i < next || !word(c) || text[..i].chars().next_back().is_some_and(|p| word(p) || p == '-') {
                continue;
            }
            let hit = forms.iter().find(|(f, _)| {
                let hay = if f.bytes().any(|b| b.is_ascii_uppercase()) { text } else { lower.as_str() };
                hay.as_bytes()[i..].starts_with(f.as_bytes())
                    && hay.is_char_boundary(i + f.len())
                    && !text[i + f.len()..].chars().next().is_some_and(word)
            });
            if let Some((f, k)) = hit {
                out.push((i, i + f.len(), *k));
                next = i + f.len();
            }
        }
        out
    }

    /// Every vessel a topic is behind.
    pub fn vessels_of(&self, topic: &str) -> Vec<ProcessType> {
        let mut v: Vec<ProcessType> =
            self.vessels.iter().filter(|(_, ts)| ts.iter().any(|t| t == topic)).map(|(p, _)| p.clone()).collect();
        v.sort_by_key(|p| p.tier());
        v
    }
}

/// Laws first, then ideas, techniques, processes, apparatus and history.
fn kind_rank(k: TopicKind) -> u8 {
    match k {
        TopicKind::Law => 0,
        TopicKind::Concept => 1,
        TopicKind::Technique => 2,
        TopicKind::Process => 3,
        TopicKind::Apparatus => 4,
        TopicKind::Event => 5,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = r#"(
        units: [("energy", "Energy and rates")],
        topics: {
            "Catalysis": (unit: "energy", kind: Concept, title: "Catalysis", url: "https://en.wikipedia.org/wiki/Catalysis", lead: "Speeding up."),
            "Arrhenius": (unit: "energy", kind: Law, title: "Arrhenius equation", url: "https://en.wikipedia.org/wiki/Arrhenius_equation"),
            "PackedBed": (unit: "lab", kind: Apparatus, title: "Packed bed", url: "u"),
        },
        reactions: { 7: ["Catalysis", "Gone"] },
        vessels: { Catalysis: ["PackedBed", "Catalysis"] },
        eras: { "Modern": ["Catalysis"] },
        substances: { 1: (title: "Hydrogen", url: "u", revised: "2026-11-01", lead: "The lightest.", sections: [("History", "Cavendish.")]) },
        values: { 1: (melting_c: Some(-259.16), boiling_c: Some(-252.88), density: Some(0.00008988)), 2: (phase_note: Some("Decomposes at 132 °C")) },
        glossary: {
            "Nitrite": (term: "Nitrite", text: "NO2-.", url: "u", forms: ["nitrites", "nitrite"]),
            "Nitrate": (term: "Nitrate", text: "NO3-.", url: "u", lesson: Some("Catalysis"), forms: ["nitrates", "nitrate"]),
            "Toxic": (term: "Toxic", text: "Harmful.", url: "u", forms: ["toxic"]),
            "pH": (term: "pH", text: "Acidity.", url: "u", forms: ["pH"]),
            "Oxide": (term: "Oxide", text: "With oxygen.", url: "u", forms: ["dioxide", "oxide"]),
        },
        substance_terms: { 1: ["Nitrite", "Nitrate"] },
    )"#;

    #[test]
    fn pages_read_and_link() {
        let p: Pages = ron::from_str(SAMPLE).expect("reads");
        assert_eq!(
            p.reaction_topics(7, &ProcessType::Catalysis),
            vec!["Catalysis", "PackedBed"],
            "no repeats, no unknown keys"
        );
        let units = p.unit_topics("energy");
        assert_eq!(units[0].0, "Arrhenius", "laws come first");
        assert_eq!(p.reactions_of("Catalysis"), vec![7]);
        assert_eq!(p.vessels_of("PackedBed"), vec![ProcessType::Catalysis]);
        assert_eq!(p.substances[&1].sections[0].0, "History");
    }

    #[test]
    fn terms_are_found_as_whole_words() {
        let p: Pages = ron::from_str(SAMPLE).expect("reads");
        assert_eq!(p.substance_terms[&1], vec!["Nitrite", "Nitrate"]);
        let keys: Vec<String> = ["Nitrite", "Nitrate", "Toxic", "pH", "Oxide"].iter().map(|s| s.to_string()).collect();
        let text = "Potassium Nitrite is not nitrates; non-toxic but toxic; PH or pH; carbon dioxide, oxidex.";
        let found: Vec<(&str, &str)> =
            p.term_spans(text, &keys).into_iter().map(|(a, b, k)| (&text[a..b], k)).collect();
        assert_eq!(
            found,
            vec![
                ("Nitrite", "Nitrite"),
                ("nitrates", "Nitrate"),
                ("toxic", "Toxic"),
                ("pH", "pH"),
                ("dioxide", "Oxide")
            ],
            "any case for a lowercase form, exactly as written for 'pH', whole words only, none after a hyphen"
        );
        assert!(p.term_spans("Ünitrite", &keys).is_empty(), "a letter outside ASCII is part of the word");
    }

    #[test]
    fn checked_values_replace_the_librarys() {
        let p: Pages = ron::from_str(SAMPLE).expect("reads");
        let mut subs = Substances::default();
        for id in [1, 2] {
            let mut s = crate::data::substances::Substance::blank(id);
            s.melting_point_c = Some(560.0);
            s.boiling_point_c = Some(132.0);
            subs.0.insert(id, s);
        }
        assert_eq!(p.apply_values(&mut subs), 2);
        assert_eq!(subs.0[&1].boiling_point_c, Some(-252.88));
        assert_eq!(subs.0[&2].melting_point_c, None, "an unknown value clears the library's");
        assert_eq!(subs.0[&2].phase_note.as_deref(), Some("Decomposes at 132 °C"));
    }
}
